-- TC Assistant database setup (generated by "npm run build:sql": edit supabase/migrations/ instead).
-- Paste this whole file into Supabase: SQL Editor > New query > Run.
-- It is safe to run more than once, on a new or an existing project.

-- ===== 0001_initial.sql =====
-- 0001: the tables the app launched with (people, transactions, tasks, documents,
-- email drafts, settings, templates), each with a user_id column and a lock (row
-- level security) so a login can only see and change its own rows.
-- Safe to run more than once.

create table if not exists public.people (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null default auth.uid() references auth.users (id) on delete cascade,
  name       text not null,
  email      text not null,
  phone      text not null default '',
  role       text not null check (role in ('client', 'agent')),
  created_at timestamptz not null default now()
);

create table if not exists public.transactions (
  id               uuid primary key default gen_random_uuid(),
  user_id          uuid not null default auth.uid() references auth.users (id) on delete cascade,
  type             text not null check (type in ('buyer', 'seller')),
  status           text not null default 'active'
                   check (status in ('active', 'pending', 'closed', 'cancelled')),
  property_address text not null,
  client_id        uuid not null references public.people (id),
  agent_id         uuid not null references public.people (id),
  contract_date    date,
  closing_date     date,
  price            numeric,
  notes            text not null default '',
  created_at       date not null default current_date,
  archived         boolean not null default false
);

create table if not exists public.tasks (
  id             uuid primary key default gen_random_uuid(),
  user_id        uuid not null default auth.uid() references auth.users (id) on delete cascade,
  transaction_id uuid not null references public.transactions (id) on delete cascade,
  title          text not null,
  due_date       date,
  status         text not null default 'open' check (status in ('open', 'done', 'skipped')),
  key            text,
  category       text
);

create table if not exists public.documents (
  id             uuid primary key default gen_random_uuid(),
  user_id        uuid not null default auth.uid() references auth.users (id) on delete cascade,
  transaction_id uuid not null references public.transactions (id) on delete cascade,
  name           text not null,
  required       boolean not null default true,
  status         text not null default 'needed' check (status in ('needed', 'requested', 'received')),
  due_date       date
);

create table if not exists public.email_drafts (
  id             uuid primary key default gen_random_uuid(),
  user_id        uuid not null default auth.uid() references auth.users (id) on delete cascade,
  transaction_id uuid not null references public.transactions (id) on delete cascade,
  recipient_id   uuid references public.people (id),
  recipient_email text,
  kind           text not null check (kind in ('welcome', 'follow-up', 'ai')),
  subject        text not null,
  body           text not null,
  status         text not null default 'draft' check (status in ('draft', 'approved', 'sent')),
  created_at     timestamptz not null default now(),
  sent_at        timestamptz,
  ai_info        jsonb
);

create table if not exists public.settings (
  user_id uuid primary key default auth.uid() references auth.users (id) on delete cascade,
  name    text not null default '',
  title   text not null default 'Transaction Coordinator',
  company text not null default '',
  default_transaction_type text not null default 'buyer'
                           check (default_transaction_type in ('buyer', 'seller')),
  follow_up_days integer not null default 7,
  task_categories jsonb
);

-- Your edited checklists and email wording, one row per account.
create table if not exists public.templates (
  user_id    uuid primary key default auth.uid() references auth.users (id) on delete cascade,
  checklists jsonb not null,
  emails     jsonb not null
);

-- Columns added after the first release. On a database made earlier these
-- add what is missing; on a new one they do nothing.
alter table public.transactions add column if not exists archived boolean not null default false;
alter table public.tasks add column if not exists category text;
alter table public.email_drafts add column if not exists recipient_email text;
alter table public.settings add column if not exists default_transaction_type text not null default 'buyer'
  check (default_transaction_type in ('buyer', 'seller'));
alter table public.settings add column if not exists follow_up_days integer not null default 7;
alter table public.settings add column if not exists task_categories jsonb;

-- AI drafting: a new kind of draft, the information it was written from, and
-- drafts for people who aren't saved on the deal (a lender, a title officer).
alter table public.email_drafts add column if not exists ai_info jsonb;
alter table public.email_drafts alter column recipient_id drop not null;
alter table public.email_drafts drop constraint if exists email_drafts_kind_check;
alter table public.email_drafts add constraint email_drafts_kind_check
  check (kind in ('welcome', 'follow-up', 'ai'));

-- Indexes: make "all tasks for this deal" style lookups fast.
create index if not exists transactions_user_idx on public.transactions (user_id);
create index if not exists people_user_idx       on public.people (user_id);
create index if not exists tasks_transaction_idx on public.tasks (transaction_id);
create index if not exists documents_transaction_idx on public.documents (transaction_id);
create index if not exists drafts_transaction_idx on public.email_drafts (transaction_id);

-- The locks: signed-in users can only touch rows where user_id is their own.
do $$
declare t text;
begin
  foreach t in array array['people', 'transactions', 'tasks', 'documents', 'email_drafts', 'settings', 'templates']
  loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists "own rows" on public.%I', t);
    execute format(
      'create policy "own rows" on public.%I for all to authenticated
         using (user_id = (select auth.uid()))
         with check (user_id = (select auth.uid()))', t);
  end loop;
end $$;

-- Make Supabase notice the new tables and columns right away.
notify pgrst, 'reload schema';

-- ===== 0002_security_hardening.sql =====
-- 0002: security hardening. Safe to run more than once.
--
--  1. Only signed-in users can touch the tables at all (the anonymous role gets nothing).
--  2. A record can only point at records of the SAME account. Before this, a row
--     was locked to its owner, but a task could still be attached to somebody
--     else's deal if you knew its id.
--  3. The database itself refuses oversized or malformed input, whatever sent it.
--  4. A version marker so the app can tell when the database is behind.

-- 1. Privileges -------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array['people', 'transactions', 'tasks', 'documents', 'email_drafts', 'settings', 'templates']
  loop
    execute format('revoke all on public.%I from anon, public', t);
    execute format('revoke all on public.%I from authenticated', t);
    execute format('grant select, insert, update, delete on public.%I to authenticated', t);
  end loop;
end $$;
alter default privileges in schema public revoke all on tables from anon;

-- 2. Same-account references --------------------------------------------------
-- A unique (id, user_id) pair lets other tables point at "this record, owned by
-- this same account" in one step.
create unique index if not exists people_id_user_key       on public.people (id, user_id);
create unique index if not exists transactions_id_user_key on public.transactions (id, user_id);

alter table public.transactions drop constraint if exists transactions_client_id_fkey;
alter table public.transactions drop constraint if exists transactions_agent_id_fkey;
alter table public.transactions drop constraint if exists transactions_client_same_account;
alter table public.transactions drop constraint if exists transactions_agent_same_account;
alter table public.transactions add constraint transactions_client_same_account
  foreign key (client_id, user_id) references public.people (id, user_id);
alter table public.transactions add constraint transactions_agent_same_account
  foreign key (agent_id, user_id) references public.people (id, user_id);

alter table public.tasks drop constraint if exists tasks_transaction_id_fkey;
alter table public.tasks drop constraint if exists tasks_transaction_same_account;
alter table public.tasks add constraint tasks_transaction_same_account
  foreign key (transaction_id, user_id) references public.transactions (id, user_id) on delete cascade;

alter table public.documents drop constraint if exists documents_transaction_id_fkey;
alter table public.documents drop constraint if exists documents_transaction_same_account;
alter table public.documents add constraint documents_transaction_same_account
  foreign key (transaction_id, user_id) references public.transactions (id, user_id) on delete cascade;

alter table public.email_drafts drop constraint if exists email_drafts_transaction_id_fkey;
alter table public.email_drafts drop constraint if exists email_drafts_recipient_id_fkey;
alter table public.email_drafts drop constraint if exists email_drafts_transaction_same_account;
alter table public.email_drafts drop constraint if exists email_drafts_recipient_same_account;
alter table public.email_drafts add constraint email_drafts_transaction_same_account
  foreign key (transaction_id, user_id) references public.transactions (id, user_id) on delete cascade;
-- recipient_id may be empty (an AI draft to a typed address); a filled one must be the same account's contact.
alter table public.email_drafts add constraint email_drafts_recipient_same_account
  foreign key (recipient_id, user_id) references public.people (id, user_id);

-- 3. Input limits -------------------------------------------------------------
-- "not valid" means: enforced for every new or changed row, without failing on
-- rows that already exist.
alter table public.people drop constraint if exists people_input_ck;
alter table public.people add constraint people_input_ck check (
  char_length(btrim(name)) between 1 and 200
  and char_length(phone) <= 50
  and (email = '' or (char_length(email) <= 320 and email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'))
) not valid;

alter table public.transactions drop constraint if exists transactions_input_ck;
alter table public.transactions add constraint transactions_input_ck check (
  char_length(btrim(property_address)) between 1 and 300
  and char_length(notes) <= 10000
  and (price is null or (price >= 0 and price < 1000000000000))
) not valid;

alter table public.tasks drop constraint if exists tasks_input_ck;
alter table public.tasks add constraint tasks_input_ck check (
  char_length(btrim(title)) between 1 and 300
  and (category is null or char_length(category) <= 100)
  and (key is null or char_length(key) <= 100)
) not valid;

alter table public.documents drop constraint if exists documents_input_ck;
alter table public.documents add constraint documents_input_ck check (
  char_length(btrim(name)) between 1 and 300
) not valid;

alter table public.email_drafts drop constraint if exists email_drafts_input_ck;
alter table public.email_drafts add constraint email_drafts_input_ck check (
  char_length(subject) <= 500
  and char_length(body) <= 40000
  and (recipient_email is null or recipient_email = ''
       or (char_length(recipient_email) <= 320 and recipient_email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'))
  and (ai_info is null or octet_length(ai_info::text) <= 100000)
) not valid;

alter table public.settings drop constraint if exists settings_input_ck;
alter table public.settings add constraint settings_input_ck check (
  char_length(name) <= 200 and char_length(title) <= 200 and char_length(company) <= 200
  and follow_up_days between 1 and 365
  and (task_categories is null or octet_length(task_categories::text) <= 20000)
) not valid;

alter table public.templates drop constraint if exists templates_input_ck;
alter table public.templates add constraint templates_input_ck check (
  octet_length(checklists::text) <= 200000 and octet_length(emails::text) <= 200000
) not valid;

-- 4. Version marker -------------------------------------------------------------
create table if not exists public.app_schema_version (
  version    integer primary key,
  applied_at timestamptz not null default now()
);
insert into public.app_schema_version (version) values (1), (2) on conflict do nothing;
alter table public.app_schema_version enable row level security;
drop policy if exists "read version" on public.app_schema_version;
create policy "read version" on public.app_schema_version for select to authenticated using (true);
revoke all on public.app_schema_version from anon, public, authenticated;
grant select on public.app_schema_version to authenticated;

notify pgrst, 'reload schema';

-- ===== 0003_document_files.sql =====
-- 0003: file uploads for deals. Safe to run more than once.
--
--  * A private storage bucket, "deal-documents" (nothing is public).
--  * A table that records each uploaded file and which deal / checklist document it belongs to.
--  * Locks: you can only see, add or delete files whose first folder is YOUR user id, and
--    only into a deal you own. Files are never edited in place.
--
-- File paths look like  <user id>/<deal id>/<random>-<file name>

-- 1. The record of each file ---------------------------------------------------
create unique index if not exists documents_id_user_key on public.documents (id, user_id);

create table if not exists public.document_files (
  id             uuid primary key default gen_random_uuid(),
  user_id        uuid not null default auth.uid() references auth.users (id) on delete cascade,
  transaction_id uuid not null,
  document_id    uuid,
  file_name      text not null,
  mime_type      text not null,
  size_bytes     bigint not null,
  storage_path   text not null unique,
  created_at     timestamptz not null default now()
);

alter table public.document_files drop constraint if exists document_files_transaction_same_account;
alter table public.document_files add constraint document_files_transaction_same_account
  foreign key (transaction_id, user_id) references public.transactions (id, user_id) on delete cascade;
-- If the checklist item is deleted the file stays on the deal.
alter table public.document_files drop constraint if exists document_files_document_same_account;
alter table public.document_files add constraint document_files_document_same_account
  foreign key (document_id, user_id) references public.documents (id, user_id) on delete set null (document_id);

alter table public.document_files drop constraint if exists document_files_input_ck;
alter table public.document_files add constraint document_files_input_ck check (
  char_length(btrim(file_name)) between 1 and 200
  and file_name !~ '[/\\[:cntrl:]]'
  and size_bytes between 1 and 10485760
  and mime_type in (
    'application/pdf', 'image/png', 'image/jpeg', 'image/webp', 'image/heic',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    'text/plain', 'text/csv'
  )
  and char_length(storage_path) <= 400
  and storage_path not like '%..%'
  and storage_path like user_id::text || '/' || transaction_id::text || '/%'
);

create index if not exists document_files_transaction_idx on public.document_files (transaction_id);

alter table public.document_files enable row level security;
drop policy if exists "own rows" on public.document_files;
create policy "own rows" on public.document_files for all to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));
revoke all on public.document_files from anon, public, authenticated;
grant select, insert, update, delete on public.document_files to authenticated;

-- 2. The private bucket ---------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'deal-documents', 'deal-documents', false, 10485760,
  array[
    'application/pdf', 'image/png', 'image/jpeg', 'image/webp', 'image/heic',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    'text/plain', 'text/csv'
  ]
)
on conflict (id) do update
  set public = false,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

-- 3. The locks on the files themselves ------------------------------------------
-- No UPDATE policy on purpose: a stored file is never changed, only added or removed.
drop policy if exists "deal files: read own" on storage.objects;
create policy "deal files: read own" on storage.objects for select to authenticated
  using (bucket_id = 'deal-documents' and (storage.foldername(name))[1] = (select auth.uid())::text);

drop policy if exists "deal files: add to own deals" on storage.objects;
create policy "deal files: add to own deals" on storage.objects for insert to authenticated
  with check (
    bucket_id = 'deal-documents'
    and (storage.foldername(name))[1] = (select auth.uid())::text
    and exists (
      select 1 from public.transactions t
      where t.id::text = (storage.foldername(name))[2] and t.user_id = (select auth.uid())
    )
  );

drop policy if exists "deal files: delete own" on storage.objects;
create policy "deal files: delete own" on storage.objects for delete to authenticated
  using (bucket_id = 'deal-documents' and (storage.foldername(name))[1] = (select auth.uid())::text);

-- 4. Version marker ----------------------------------------------------------------
insert into public.app_schema_version (version) values (3) on conflict do nothing;

notify pgrst, 'reload schema';

-- ===== 0004_daily_reminders.sql =====
-- 0004: daily reminder emails. Safe to run more than once.
--
-- A scheduled job INSIDE Supabase (see supabase/reminders-schedule.sql) emails each
-- person who switched reminders on a plain-text list of what is overdue or coming up.
--
--  * Only ever sent to the account's own login email, never to an address typed in.
--  * The email service key lives in Supabase Vault, not in the app.
--  * The sending functions are not callable by logged-in users or visitors, except
--    send_test_reminder(), which can only email YOU and is rate limited.

-- 1. Your choices (these are yours to change) ---------------------------------------
alter table public.settings add column if not exists reminders_enabled boolean not null default false;
alter table public.settings add column if not exists reminder_hour smallint not null default 8;
alter table public.settings add column if not exists reminder_timezone text not null default 'America/New_York';

alter table public.settings drop constraint if exists settings_reminder_ck;
alter table public.settings add constraint settings_reminder_ck check (
  reminder_hour between 0 and 23 and char_length(reminder_timezone) between 1 and 64
);

-- 2. Bookkeeping and setup nobody but the server can touch ----------------------------
create table if not exists public.reminder_state (
  user_id    uuid primary key references auth.users (id) on delete cascade,
  last_sent  date,
  test_at    timestamptz,
  test_day   date,
  test_count integer not null default 0
);
create table if not exists public.reminder_config (
  id           integer primary key check (id = 1),
  app_url      text,
  from_address text
);
-- Row level security on with no policies = nobody (except the server) can read or write.
alter table public.reminder_state enable row level security;
alter table public.reminder_config enable row level security;
revoke all on public.reminder_state from anon, public, authenticated;
revoke all on public.reminder_config from anon, public, authenticated;

-- 3. The work, in a schema the API does not expose -------------------------------------
create schema if not exists app_private;
revoke all on schema app_private from public, anon, authenticated;

-- What is overdue or coming up for one person. Mirrors the follow-ups page:
-- open tasks, documents not yet received, and closing dates, on deals that are
-- not archived and are active or pending. Returns null when there is nothing.
create or replace function app_private.reminder_digest(p_user uuid, p_today date)
returns jsonb language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  win int; cutoff date; r record; days int; label text;
  over_lines text[] := '{}'; soon_lines text[] := '{}'; n_over int := 0; n_soon int := 0;
  cfg_url text; body text;
begin
  select coalesce(follow_up_days, 7) into win from settings where user_id = p_user;
  win := coalesce(win, 7);
  cutoff := p_today + win;

  for r in
    select x.deal, x.title, x.due from (
      select t.property_address as deal, k.title, k.due
      from transactions t
      cross join lateral (
        select title, due_date as due from tasks
          where transaction_id = t.id and user_id = p_user and status = 'open' and due_date is not null and due_date <= cutoff
        union all
        select name, due_date from documents
          where transaction_id = t.id and user_id = p_user and status <> 'received' and due_date is not null and due_date <= cutoff
        union all
        select 'Closing date', t.closing_date where t.closing_date is not null and t.closing_date <= cutoff
      ) k
      where t.user_id = p_user and not t.archived and t.status in ('active', 'pending')
    ) x order by x.due, x.deal, x.title
  loop
    days := r.due - p_today;
    label := case when days < 0 then (-days) || case when days = -1 then ' day overdue' else ' days overdue' end
                  when days = 0 then 'due today'
                  else 'due in ' || days || case when days = 1 then ' day' else ' days' end end;
    if days < 0 then
      n_over := n_over + 1;
      if n_over <= 25 then over_lines := over_lines || format('  - %s: %s (%s)', left(regexp_replace(r.deal, '\s+', ' ', 'g'), 80), left(regexp_replace(r.title, '\s+', ' ', 'g'), 120), label); end if;
    else
      n_soon := n_soon + 1;
      if n_soon <= 25 then soon_lines := soon_lines || format('  - %s: %s (%s)', left(regexp_replace(r.deal, '\s+', ' ', 'g'), 80), left(regexp_replace(r.title, '\s+', ' ', 'g'), 120), label); end if;
    end if;
  end loop;

  if n_over + n_soon = 0 then return null; end if;

  select app_url into cfg_url from reminder_config where id = 1;
  body := format('You have %s overdue and %s coming up in the next %s days.', n_over, n_soon, win) || E'\n';
  if n_over > 0 then
    body := body || E'\nOVERDUE (' || n_over || E')\n' || array_to_string(over_lines, E'\n') || E'\n';
    if n_over > 25 then body := body || format('  ...and %s more', n_over - 25) || E'\n'; end if;
  end if;
  if n_soon > 0 then
    body := body || E'\nCOMING UP (' || n_soon || E')\n' || array_to_string(soon_lines, E'\n') || E'\n';
    if n_soon > 25 then body := body || format('  ...and %s more', n_soon - 25) || E'\n'; end if;
  end if;
  if coalesce(cfg_url, '') <> '' then
    body := body || E'\nOpen TC Assistant: ' || cfg_url || E'/follow-ups\nTurn these emails off in Settings: ' || cfg_url || E'/settings\n';
  end if;
  return jsonb_build_object('overdue', n_over, 'soon', n_soon, 'text', body);
end $$;

-- Sends one email to the account's own login address. Returns 'sent', 'empty' or 'unconfigured'.
create or replace function app_private.deliver_reminder(p_user uuid, p_today date, p_send_empty boolean)
returns text language plpgsql security definer set search_path = public, pg_temp as $$
declare digest jsonb; to_email text; api_key text; sender text; subject text; body text;
begin
  digest := app_private.reminder_digest(p_user, p_today);
  if digest is null and not p_send_empty then return 'empty'; end if;

  select email into to_email from auth.users where id = p_user;
  select decrypted_secret into api_key from vault.decrypted_secrets where name = 'resend_api_key' limit 1;
  select from_address into sender from reminder_config where id = 1;
  if coalesce(to_email, '') = '' or coalesce(api_key, '') = '' or coalesce(sender, '') = '' then
    raise warning 'reminders: not set up yet (need the Resend key in Vault and a from address in reminder_config)';
    return 'unconfigured';
  end if;

  if digest is null then
    subject := 'TC Assistant: nothing is due';
    body := 'Test email from TC Assistant. Nothing is overdue or coming up right now, so a real reminder would be skipped today.';
  else
    subject := format('TC Assistant: %s overdue, %s coming up', digest->>'overdue', digest->>'soon');
    body := digest->>'text';
  end if;

  perform net.http_post(
    url := 'https://api.resend.com/emails',
    headers := jsonb_build_object('Authorization', 'Bearer ' || api_key, 'Content-Type', 'application/json'),
    body := jsonb_build_object('from', sender, 'to', jsonb_build_array(to_email), 'subject', subject, 'text', body)
  );
  return 'sent';
end $$;

-- Called by the hourly schedule. Sends to everyone whose chosen hour it is right now
-- (in their own time zone) who has not already had today's email.
create or replace function app_private.send_due_reminders(p_now timestamptz default now())
returns integer language plpgsql security definer set search_path = public, pg_temp as $$
declare r record; local_ts timestamp; local_day date; outcome text; sent int := 0;
begin
  for r in select user_id, reminder_hour, reminder_timezone from settings where reminders_enabled loop
    begin
      local_ts := p_now at time zone r.reminder_timezone;
      continue when extract(hour from local_ts)::int <> r.reminder_hour;
      local_day := local_ts::date;
      continue when exists (select 1 from reminder_state where user_id = r.user_id and last_sent = local_day);

      outcome := app_private.deliver_reminder(r.user_id, local_day, false);
      if outcome in ('sent', 'empty') then
        insert into reminder_state (user_id, last_sent) values (r.user_id, local_day)
          on conflict (user_id) do update set last_sent = excluded.last_sent;
      end if;
      if outcome = 'sent' then sent := sent + 1; end if;
    exception when others then
      raise warning 'reminders: skipped one account (%)', sqlerrm;
    end;
  end loop;
  return sent;
end $$;

revoke all on function app_private.reminder_digest(uuid, date) from public, anon, authenticated;
revoke all on function app_private.deliver_reminder(uuid, date, boolean) from public, anon, authenticated;
revoke all on function app_private.send_due_reminders(timestamptz) from public, anon, authenticated;

-- 4. The "Send me a test email" button ---------------------------------------------------
-- Takes no arguments: it can only ever email the person who is logged in.
create or replace function public.send_test_reminder()
returns text language plpgsql security definer set search_path = public, pg_temp as $$
declare uid uuid := auth.uid(); st record; tz text; today date;
begin
  if uid is null then raise exception 'Please log in first.' using errcode = '28000'; end if;
  insert into reminder_state (user_id) values (uid) on conflict (user_id) do nothing;
  select * into st from reminder_state where user_id = uid for update;
  if st.test_at is not null and st.test_at > now() - interval '2 minutes' then
    raise exception 'Please wait a couple of minutes before sending another test.';
  end if;
  if st.test_day = current_date and st.test_count >= 5 then
    raise exception 'That is enough test emails for today. Try again tomorrow.';
  end if;
  update reminder_state
     set test_at = now(), test_day = current_date,
         test_count = case when test_day = current_date then test_count + 1 else 1 end
   where user_id = uid;
  select reminder_timezone into tz from settings where user_id = uid;
  begin
    today := (now() at time zone coalesce(tz, 'America/New_York'))::date;
  exception when others then
    today := current_date;
  end;
  return app_private.deliver_reminder(uid, today, true);
end $$;

revoke all on function public.send_test_reminder() from public, anon;
grant execute on function public.send_test_reminder() to authenticated;

-- 5. Version marker -----------------------------------------------------------------------
insert into public.app_schema_version (version) values (4) on conflict do nothing;

notify pgrst, 'reload schema';
